from typing import Optional
from .ah_report_configuration import AHReportConfiguration
from .models.base import AHBaseReportInfo
from .models.reports import AHLogReport, AHAlertReport, AHAdoptionReport
from .models.model_reports import AHModelAccessibilityReport, AHModelRecordReport


class AHReportBuilder:
    def __init__(self, configuration: AHReportConfiguration):
        self.configuration = configuration

    def build_base_info(self) -> AHBaseReportInfo:
        return AHBaseReportInfo(
            app_version=self.configuration.get_app_version(),
            app_id=self.configuration.get_app_id(),
            username=self.configuration.get_username(),
            user_agent=self.configuration.get_user_agent(),
        )

    def build_log_report(self, message: str, sub_type: str,
                         user_defined: Optional[dict] = None) -> AHLogReport:
        return AHLogReport(
            base_info=self.build_base_info(),
            message=message,
            sub_type=sub_type,
            user_defined=user_defined,
        )

    def build_alert_report(self, alert_type: str, status: str, title: str,
                           alert_message: Optional[str] = None, alert_level: Optional[str] = None,
                           service_name: Optional[str] = None, request_id: Optional[str] = None,
                           api_url: Optional[str] = None, response_time: Optional[float] = None,
                           error_code: Optional[str] = None,
                           ext_data: Optional[dict] = None) -> AHAlertReport:
        return AHAlertReport(
            base_info=self.build_base_info(),
            alert_type=alert_type,
            status=status,
            title=title,
            alert_message=alert_message,
            alert_level=alert_level,
            service_name=service_name,
            request_id=request_id,
            ide_type=str(self.configuration.get_ide_type()),
            mcp_version=self.configuration.get_mcp_version(),
            api_url=api_url,
            response_time=response_time,
            error_code=error_code,
            ext_data=ext_data,
        )

    def build_adoption_report(self, is_accepted: bool, accept_code: str, file_path: str,
                              repository_url: str, prompt_count: int, ask_type: int,
                              ext: Optional[dict] = None) -> AHAdoptionReport:
        return AHAdoptionReport(
            base_info=self.build_base_info(),
            is_accepted=is_accepted,
            accept_code=accept_code,
            file_path=file_path,
            repository_url=repository_url,
            prompt_count=prompt_count,
            ide_type=self.configuration.get_ide_type(),
            ask_type=ask_type,
            ext=ext,
        )

    def build_model_accessibility_report(self, username: str, model: str,
                                         source_type: Optional[str] = None,
                                         git_url: Optional[str] = None) -> AHModelAccessibilityReport:
        return AHModelAccessibilityReport(
            base_info=self.build_base_info(),
            username=username,
            model=model,
            source_type=source_type or '1',
            git_url=git_url,
        )

    def build_model_record_report(self, username: str, model: str,
                                  source_type: Optional[str] = None) -> AHModelRecordReport:
        return AHModelRecordReport(
            base_info=self.build_base_info(),
            username=username,
            model=model,
            source_type=source_type or '1',
        )
